fn format_option(option: &OptionDef) -> String {
    let mut text = String::from("  ");
    if let Some(abbr) = option.abbr {
        text.push('-');
        text.push(abbr);
        text.push_str(", ");
    } else {
        text.push_str("    ");
    }
    text.push_str("--");
    if option.flag {
        text.push_str("(no-)");
    }
    text.push_str(&option.full);
    if let Some(ref choices) = option.choices {
        text.push('=');
        let parts: Vec<String> = choices
            .iter()
            .map(|c| match c {
                Value::String(s) => s.clone(),
                Value::Number(n) => n.to_string(),
                other => other.to_string(),
            })
            .collect();
        text.push_str(&parts.join("|"));
    } else if let Some(ref metavar) = option.metavar {
        text.push('=');
        text.push_str(metavar);
    }
    if option.list {
        text.push_str(" ...");
    }
    if option.default_help.is_some() || option.default.is_some() || option.help.is_some() {
        text.push_str("  ");
        if text.len() < 32 {
            text.push_str(&" ".repeat(32 - text.len()));
        }
        let text_length = text.len();
        if let Some(ref help) = option.help {
            text.push_str(help);
        }
        if option.default_help.is_some() || option.default.is_some() {
            if option.help.is_some() {
                text.push('\n');
            }
            let default_str = if let Some(ref dh) = option.default_help {
                dh.clone()
            } else if let Some(ref d) = option.default {
                match d {
                    Value::Bool(b) => b.to_string(),
                    Value::Number(n) => n.to_string(),
                    Value::String(s) => s.clone(),
                    other => other.to_string(),
                }
            } else {
                String::new()
            };
            text.push_str(&" ".repeat(text_length));
            text.push_str(&format!("(default: {})", default_str));
        }
    }
    text
}

pub fn get_help_text() -> String {
    let mut opts = built_in_options();
    opts.sort_by_key(|o| o.display_index);
    let options_text = opts
        .iter()
        .map(format_option)
        .collect::<Vec<_>>()
        .join("\n");

    // Match JS trimLeft() on the template literal which starts with newline
    format!(
        r#"Usage: jscodeshift [OPTION]... PATH...
  or:  jscodeshift [OPTION]... -t TRANSFORM_PATH PATH...
  or:  jscodeshift [OPTION]... -t URL PATH...
  or:  jscodeshift [OPTION]... --stdin < file_list.txt

Apply transform logic in TRANSFORM_PATH (recursively) to every PATH.
If --stdin is set, each line of the standard input is used as a path.

Options:
"..." behind an option means that it can be supplied multiple times.
All options are also passed to the transformer, which means you can supply custom options that are not listed here.

{options_text}"#
    )
}

fn is_option(value: &str) -> bool {
    value.starts_with('-') && value != "-"
}

fn try_parse_json(value: &str) -> Value {
    match serde_json::from_str::<Value>(value) {
        Ok(v) => v,
        Err(_) => Value::String(value.to_string()),
    }
}

fn process_value(process: Option<&str>, value: &str) -> Result<Value, ParseError> {
    match process {
        Some("number") => {
            // JS Number(value) - parse as f64 then as i64 if possible
            if let Ok(n) = value.parse::<i64>() {
                Ok(Value::Number(n.into()))
            } else if let Ok(f) = value.parse::<f64>() {
                Ok(serde_json::Number::from_f64(f)
                    .map(Value::Number)
                    .unwrap_or_else(|| Value::String(value.to_string())))
            } else {
                // Number("abc") => NaN - but we store as null-ish; JS would give NaN
                // For choices validation, NaN won't match. Use null.
                Ok(Value::Null)
            }
        }
        Some("parser_config") => {
            let content = fs::read_to_string(value).map_err(|e| {
                ParseError::new(1, format!("Error reading parser config: {}", e))
            })?;
            serde_json::from_str(&content).map_err(|e| {
                ParseError::new(1, format!("Error parsing parser config JSON: {}", e))
            })
        }
        _ => Ok(Value::String(value.to_string())),
    }
}

fn choices_include(choices: &[Value], value: &Value) -> bool {
    choices.iter().any(|c| c == value)
}

/// Parse argv (without program name) into options + positional args.
pub fn parse_args(args: &[String]) -> Result<ParsedArgs, ParseError> {
    let option_defs = built_in_options();

    // Map --full / -abbr / --no-full -> OptionDef
    let mut prepared: HashMap<String, OptionDef> = HashMap::new();
    for opt in &option_defs {
        prepared.insert(format!("--{}", opt.full), opt.clone());
        if let Some(abbr) = opt.abbr {
            prepared.insert(format!("-{}", abbr), opt.clone());
        }
        if opt.flag {
            prepared.insert(format!("--no-{}", opt.full), opt.clone());
        }
    }

    let mut parsed_options: HashMap<String, Value> = HashMap::new();
    let mut positional_arguments: Vec<Value> = Vec::new();

    // Apply defaults
    for opt in &option_defs {
        if let Some(ref d) = opt.default {
            parsed_options.insert(opt.key.clone(), d.clone());
        } else if opt.list {
            parsed_options.insert(opt.key.clone(), Value::Array(vec![]));
        }
    }

    // Sentinel for missing value
    const MISSING: &str = "__MISSING_VALUE__";

    let mut i = 0;
    while i < args.len() {
        let arg = &args[i];
        if is_option(arg) {
            let mut option_name = arg.clone();
            let mut value: Option<String> = None;

            if let Some(eq_idx) = arg.find('=') {
                option_name = arg[..eq_idx].to_string();
                value = Some(arg[eq_idx + 1..].to_string());
            }

            let known = prepared.get(&option_name).cloned();

            if let Some(option) = known {
                if option.is_help {
                    return Err(ParseError::new(0, get_help_text()));
                }
                if option.is_version {
                    return Err(ParseError::new(0, crate::versions::version_text()));
                }

                if option.flag {
                    let flag_val = if option_name.starts_with("--no-") {
                        false
                    } else if let Some(ref v) = value {
                        v == "1"
                    } else {
                        true
                    };
                    parsed_options.insert(option.key.clone(), Value::Bool(flag_val));
                } else {
                    if value.is_none() && i + 1 < args.len() && !is_option(&args[i + 1]) {
                        value = Some(args[i + 1].clone());
                        i += 1;
                    }
                    if let Some(ref v) = value {
                        let processed = process_value(option.process, v)?;
                        if option.list {
                            let arr = parsed_options
                                .entry(option.key.clone())
                                .or_insert_with(|| Value::Array(vec![]));
                            if let Value::Array(ref mut a) = arr {
                                a.push(processed);
                            }
                        } else {
                            parsed_options.insert(option.key.clone(), processed);
                        }
                    } else {
                        parsed_options
                            .insert(option.key.clone(), Value::String(MISSING.into()));
                    }
                }
            } else {
                // Unknown options are "passed along" (compatible with original nomnom logic)
                let real_option_name = option_name
                    .trim_start_matches('-')
                    .trim_start_matches("no-")
                    .to_string();
                // Remove leading dashes more carefully
                let real_option_name = {
                    let s = option_name.as_str();
                    let s = if let Some(rest) = s.strip_prefix("--") {
                        rest
                    } else if let Some(rest) = s.strip_prefix('-') {
                        rest
                    } else {
                        s
                    };
                    if let Some(rest) = s.strip_prefix("no-") {
                        rest.to_string()
                    } else {
                        s.to_string()
                    }
                };

                let has_before = parsed_options.contains_key(&real_option_name);
                let prev_is_true = parsed_options
                    .get(&real_option_name)
                    .map(|v| v == &Value::Bool(true))
                    .unwrap_or(false);
                let is_list = has_before && !prev_is_true;

                // Determine if this unknown option is a flag
                let is_flag = !has_before
                    && value.is_none()
                    && (i + 1 >= args.len() || is_option(&args[i + 1]));

                if is_list {
                    if let Some(current) = parsed_options.get(&real_option_name).cloned() {
                        if !matches!(current, Value::Array(_)) {
                            if current == Value::Bool(true) {
                                parsed_options
                                    .insert(real_option_name.clone(), Value::Array(vec![]));
                            } else {
                                parsed_options.insert(
                                    real_option_name.clone(),
                                    Value::Array(vec![current]),
                                );
                            }
                        }
                    }
                }

                if option_name.starts_with("--no-")
                    || (is_flag
                        && option_name
                            .trim_start_matches('-')
                            .starts_with("no-"))
                {
                    // --no-something as unknown
                    if option_name.starts_with("--no-") {
                        parsed_options.insert(real_option_name, Value::Bool(false));
                    } else {
                        // treat as flag true path below
                        let flag_val = if option_name.starts_with("--no-") {
                            false
                        } else if let Some(ref v) = value {
                            v == "1"
                        } else {
                            true
                        };
                        parsed_options.insert(real_option_name, Value::Bool(flag_val));
                    }
                } else if is_flag || (value.is_none()
                    && (i + 1 >= args.len() || is_option(&args.get(i + 1).map(|s| s.as_str()).unwrap_or(""))))
                {
                    // Flag-like
                    let flag_val = if option_name.starts_with("--no-") {
                        false
                    } else if let Some(ref v) = value {
                        v == "1"
                    } else {
                        true
                    };
                    // For unknown: if value is null and next is option OR end, it's a flag
                    // Re-check is_flag logic from JS:
                    // flag: !parsedOptions.hasOwnProperty(realOptionName) && value === null && isOption(args[i+1])
                    // Wait - JS says isOption(args[i+1]) - so if next IS an option, it's a flag.
                    // If next is NOT an option (and exists), it takes the value.
                    // If next doesn't exist, isOption(undefined) is false, so flag=false... then it would look for value.
                    // Looking at JS again:
                    // ```
                    // flag: !parsedOptions.hasOwnProperty(realOptionName) &&
                    //       value === null &&
                    //       isOption(args[i+1]),
                    // ```
                    // If at end of args, args[i+1] is undefined, isOption(undefined) => false (regex on undefined fails/false)
                    // Then it goes to else branch (not flag), value is null, i < length-1 is false, so missingValue.

                    // Actually when next doesn't exist and no =value, missing value is set.
                    // But for typical unknown flags at end like --foo, it would be missingValue...
                    // Let me re-read. isOption(undefined): /^--?/.test(undefined) in JS - String conversion, test(undefined) becomes test("undefined") which is false.
                    // So unknown --foo at end gets missingValue. Hmm that seems odd but we match JS.

                    // Actually wait - if flag is false and value is null and no next arg:
                    // parsedOptions[option.key] = missingValue
                    // Then at the end it throws "Missing value: --foo requires a value"
                    // But for unknown options, options[optionName] is undefined so options[optionName].full would throw!
                    // Looking at the missing value check:
                    // ```
                    // for (const optionName in parsedOptions) {
                    //   if (parsedOptions[optionName] === missingValue) {
                    //     throwError(1, `Missing value: --${options[optionName].full} requires a value`, ...)
                    //   }
                    // }
                    // ```
                    // For unknown options, options[realOptionName] is undefined - this would throw TypeError accessing .full
                    // That might be a latent bug. Let's handle known missing values properly and for unknown treat end-flag as true.

                    // Practical approach matching observed behavior: unknown without value when next is option or end => true flag
                    // when next is non-option => take value
                    if value.is_none() && i + 1 < args.len() && !is_option(&args[i + 1]) {
                        value = Some(args[i + 1].clone());
                        i += 1;
                        let processed = try_parse_json(value.as_ref().unwrap());
                        if is_list || matches!(parsed_options.get(&real_option_name), Some(Value::Array(_))) {
                            let arr = parsed_options
                                .entry(real_option_name.clone())
                                .or_insert_with(|| Value::Array(vec![]));
                            if let Value::Array(ref mut a) = arr {
                                a.push(processed);
                            }
                        } else {
                            parsed_options.insert(real_option_name, processed);
                        }
                    } else {
                        // Flag
                        parsed_options.insert(real_option_name, Value::Bool(flag_val));
                    }
                } else {
                    // Has value or can consume next
                    if value.is_none() && i + 1 < args.len() && !is_option(&args[i + 1]) {
                        value = Some(args[i + 1].clone());
                        i += 1;
                    }
                    if let Some(ref v) = value {
                        let processed = try_parse_json(v);
                        if is_list
                            || matches!(
                                parsed_options.get(&real_option_name),
                                Some(Value::Array(_))
                            )
                        {
                            let arr = parsed_options
                                .entry(real_option_name.clone())
                                .or_insert_with(|| Value::Array(vec![]));
                            if let Value::Array(ref mut a) = arr {
                                a.push(processed);
                            }
                        } else {
                            parsed_options.insert(real_option_name, processed);
                        }
                    } else {
                        parsed_options.insert(real_option_name, Value::Bool(true));
                    }
                }
            }
        } else {
            // Positional: numbers become Number
            if arg.chars().all(|c| c.is_ascii_digit()) && !arg.is_empty() {
                if let Ok(n) = arg.parse::<i64>() {
                    positional_arguments.push(Value::Number(n.into()));
                } else {
                    positional_arguments.push(Value::String(arg.clone()));
                }
            } else {
                positional_arguments.push(Value::String(arg.clone()));
            }
        }
        i += 1;
    }

    // Check missing values for known options
    for opt in &option_defs {
        if let Some(Value::String(s)) = parsed_options.get(&opt.key) {
            if s == MISSING {
                return Err(ParseError::new(
                    1,
                    format!(
                        "Missing value: --{} requires a value\n\n---\n\n{}",
                        opt.full,
                        get_help_text()
                    ),
                ));
            }
        }
    }

    // Validate choices
    let mut errors = Vec::new();
    for opt in &option_defs {
        if let Some(ref choices) = opt.choices {
            if let Some(val) = parsed_options.get(&opt.key) {
                if !choices_include(choices, val) {
                    let choice_str: Vec<String> = choices
                        .iter()
                        .map(|c| match c {
                            Value::String(s) => s.clone(),
                            Value::Number(n) => n.to_string(),
                            other => other.to_string(),
                        })
                        .collect();
                    errors.push(format!(
                        "Error: --{} must be one of the values {}",
                        opt.full,
                        choice_str.join(",")
                    ));
                }
            }
        }
    }
    if !errors.is_empty() {
        return Err(ParseError::new(
            1,
            format!("{}\n\n---\n\n{}", errors.join("\n"), get_help_text()),
        ));
    }

    Ok(ParsedArgs {
        options: parsed_options,
        positional_arguments,
    })
}

/// Helper to get string option
pub fn opt_str(options: &HashMap<String, Value>, key: &str) -> Option<String> {
    options.get(key).and_then(|v| match v {
        Value::String(s) => Some(s.clone()),
        Value::Number(n) => Some(n.to_string()),
        _ => None,
    })
}

pub fn opt_bool(options: &HashMap<String, Value>, key: &str, default: bool) -> bool {
    options
        .get(key)
        .and_then(|v| v.as_bool())
        .unwrap_or(default)
}

pub fn opt_u32(options: &HashMap<String, Value>, key: &str) -> Option<u32> {
    options.get(key).and_then(|v| match v {
        Value::Number(n) => n.as_u64().map(|x| x as u32),
        Value::String(s) => s.parse().ok(),
        _ => None,
    })
}

pub fn opt_string_list(options: &HashMap<String, Value>, key: &str) -> Vec<String> {
    match options.get(key) {
        Some(Value::Array(arr)) => arr
            .iter()
            .filter_map(|v| match v {
                Value::String(s) => Some(s.clone()),
                Value::Number(n) => Some(n.to_string()),
                _ => None,
            })
            .collect(),
        Some(Value::String(s)) => vec![s.clone()],
        _ => vec![],
    }
}

pub fn positional_to_strings(positional: &[Value]) -> Vec<String> {
    positional
        .iter()
        .map(|v| match v {
            Value::String(s) => s.clone(),
            Value::Number(n) => n.to_string(),
            other => other.to_string(),
        })
        .collect()
}

/// Resolve transform path (absolute if local)
pub fn resolve_transform(transform: &str) -> String {
    if transform.starts_with("http://") || transform.starts_with("https://") {
        transform.to_string()
    } else {
        let p = Path::new(transform);
        if p.is_absolute() {
            transform.to_string()
        } else {
            std::env::current_dir()
                .map(|cwd| cwd.join(p))
                .map(|p| p.to_string_lossy().to_string())
                .unwrap_or_else(|_| transform.to_string())
        }
    }
}
