{"path":"/workspace/codebase/rust/src/versions.rs","command":"create","file_text":"use std::path::{Path, PathBuf};
use std::process::Command;

/// Locate the package root (directory containing package.json and index.js).
pub fn package_root() -> PathBuf {
    // Try several strategies:
    // 1. JSCODESHIFT_ROOT env
    // 2. Relative to the executable
    // 3. Relative to CARGO_MANIFEST_DIR at compile time
    if let Ok(root) = std::env::var("JSCODESHIFT_ROOT") {
        return PathBuf::from(root);
    }

    if let Ok(exe) = std::env::current_exe() {
        // native/jscodeshift or target/.../jscodeshift
        if let Some(parent) = exe.parent() {
            // native/ -> package root
            let candidate = parent.parent().unwrap_or(parent);
            if candidate.join("package.json").exists() {
                return candidate.to_path_buf();
            }
            // target/release -> rust/ -> package root
            if let Some(p) = parent.parent() {
                if let Some(p2) = p.parent() {
                    if p2.join("package.json").exists() {
                        return p2.to_path_buf();
                    }
                    if let Some(p3) = p2.parent() {
                        if p3.join("package.json").exists() {
                            return p3.to_path_buf();
                        }
                    }
                }
            }
        }
    }

    // Compile-time: rust/ is inside package
    let manifest = PathBuf::from(env!("CARGO_MANIFEST_DIR"));
    if let Some(parent) = manifest.parent() {
        if parent.join("package.json").exists() {
            return parent.to_path_buf();
        }
    }

    std::env::current_dir().unwrap_or_else(|_| PathBuf::from("."))
}

fn read_pkg_version(name: &str, root: &Path) -> String {
    // Try node to resolve package version, fallback to reading node_modules
    let script = format!(
        r#"
        try {{
          const path = require('path');
          const fs = require('fs');
          function requirePackage(n) {{
            const entry = require.resolve(n);
            let dir = path.dirname(entry);
            while (dir !== '/') {{
              try {{
                const pkg = require(path.join(dir, 'package.json'));
                if (pkg.name === n) return pkg.version || '';
              }} catch (e) {{}}
              dir = path.dirname(dir);
            }}
            return '';
          }}
          if ('{name}' === 'jscodeshift') {{
            console.log(require('{root}/package.json').version);
          }} else if ('{name}' === '@babel/core' || '{name}' === 'babel') {{
            console.log(require('@babel/core').version);
          }} else {{
            console.log(requirePackage('{name}'));
          }}
        }} catch (e) {{ console.log(''); }}
        "#,
        name = name,
        root = root.display().to_string().replace('\\', "\\\\").replace('\'', "\\'")
    );

    let output = Command::new("node")
        .arg("-e")
        .arg(&script)
        .current_dir(root)
        .output();

    match output {
        Ok(out) if out.status.success() => {
            String::from_utf8_lossy(&out.stdout).trim().to_string()
        }
        _ => String::new(),
    }
}

pub fn version_text() -> String {
    let root = package_root();
    let jscodeshift = read_pkg_version("jscodeshift", &root);
    let babel = read_pkg_version("@babel/core", &root);
    let babylon = read_pkg_version("@babel/parser", &root);
    let flow = read_pkg_version("flow-parser", &root);
    let recast = read_pkg_version("recast", &root);

    format!(
        "jscodeshift: {}\n - babel: {}\n - babylon: {}\n - flow: {}\n - recast: {}\n",
        jscodeshift, babel, babylon, flow, recast
    )
}
"}

{"path":"/workspace/codebase/rust/src/ignore.rs","command":"create","file_text":"use globset::{Glob, GlobSet, GlobSetBuilder};
use std::fs;
use std::path::Path;
use std::sync::Mutex;

/// Ignore-pattern state matching src/ignoreFiles.js (picomatch-compatible globs).
pub struct IgnoreMatcher {
    patterns: Vec<String>,
    globset: Option<GlobSet>,
}

impl IgnoreMatcher {
    pub fn new() -> Self {
        Self {
            patterns: Vec::new(),
            globset: None,
        }
    }

    fn rebuild(&mut self) {
        let mut builder = GlobSetBuilder::new();
        for p in &self.patterns {
            // globset uses git-style globs; enable literal_separator false for ** behavior
            if let Ok(g) = Glob::new(p) {
                builder.add(g);
            }
            // Also try with leading **/
            if !p.starts_with("**/") && !p.starts_with('/') {
                if let Ok(g) = Glob::new(&format!("**/{}", p)) {
                    builder.add(g);
                }
            }
        }
        self.globset = builder.build().ok();
    }

    /// Add a single gitignore-style / glob pattern (mirrors addIgnorePattern).
    pub fn add_pattern(&mut self, val: &str) {
        if val.is_empty() || val.starts_with('#') {
            return;
        }
        let pattern = val.to_string();
        if !pattern.contains('/') {
            self.patterns.push(format!("**/{}", pattern));
        } else if pattern.ends_with('/') {
            self.patterns.push(format!("**/{}**", pattern));
            self.patterns.push(format!("{}**", pattern));
        }
        self.patterns.push(pattern);
        self.rebuild();
    }

    pub fn add_from_input(&mut self, input: &[String]) {
        for p in input {
            self.add_pattern(p);
        }
    }

    pub fn add_from_file(&mut self, paths: &[String]) {
        for config in paths {
            let path = Path::new(config);
            if let Ok(meta) = fs::metadata(path) {
                if meta.is_file() {
                    if let Ok(content) = fs::read_to_string(path) {
                        for line in content.split('\n') {
                            let line = line.trim_end_matches('\r');
                            self.add_pattern(line);
                        }
                    }
                }
            }
        }
    }

    pub fn should_ignore(&self, path: &str) -> bool {
        if self.patterns.is_empty() {
            return false;
        }
        // Strip leading ../ or ./ traversal prefixes (issue #556)
        let normalized = {
            let mut s = path;
            loop {
                if let Some(rest) = s.strip_prefix("../") {
                    s = rest;
                } else if let Some(rest) = s.strip_prefix("..\\") {
                    s = rest;
                } else if let Some(rest) = s.strip_prefix("./") {
                    s = rest;
                } else if let Some(rest) = s.strip_prefix(".\\") {
                    s = rest;
                } else {
                    break;
                }
            }
            s
        };

        let matches = |p: &str| -> bool {
            if let Some(ref gs) = self.globset {
                if gs.is_match(p) {
                    return true;
                }
            }
            // Fallback: simple pattern matching for common cases
            for pat in &self.patterns {
                if simple_glob_match(pat, p) {
                    return true;
                }
            }
            false
        };

        matches(path) || (normalized != path && matches(normalized))
    }
}

impl Default for IgnoreMatcher {
    fn default() -> Self {
        Self::new()
    }
}

/// Very small glob matcher covering **, *, and exact segments (dotfiles included).
fn simple_glob_match(pattern: &str, path: &str) -> bool {
    // Normalize separators
    let pattern = pattern.replace('\\', "/");
    let path = path.replace('\\', "/");
    glob_match_rec(pattern.as_bytes(), path.as_bytes())
}

fn glob_match_rec(pat: &[u8], path: &[u8]) -> bool {
    let mut pi = 0;
    let mut si = 0;
    let mut star_pi = None;
    let mut star_si = None;

    while si < path.len() {
        if pi < pat.len() && (pat[pi] == path[si] || pat[pi] == b'?') {
            // '?' should not match '/'
            if pat[pi] == b'?' && path[si] == b'/' {
                // fail this branch
            } else if pat[pi] != b'*' {
                pi += 1;
                si += 1;
                continue;
            }
        }
        if pi + 1 < pat.len() && pat[pi] == b'*' && pat[pi + 1] == b'*' {
            // **
            // skip trailing ** or **/
            let mut next = pi + 2;
            if next < pat.len() && pat[next] == b'/' {
                next += 1;
            }
            // Try match rest at every position
            if next >= pat.len() {
                return true; // ** at end matches all
            }
            // recursive: try from current si onward
            let mut k = si;
            loop {
                if glob_match_rec(&pat[next..], &path[k..]) {
                    return true;
                }
                if k >= path.len() {
                    break;
                }
                k += 1;
            }
            return false;
        }
        if pi < pat.len() && pat[pi] == b'*' {
            // single-segment *
            star_pi = Some(pi);
            star_si = Some(si);
            pi += 1;
            continue;
        }
        if let (Some(sp), Some(ss)) = (star_pi, star_si) {
            // backtrack: * cannot cross '/'
            if path[ss] == b'/' {
                star_pi = None;
                star_si = None;
                // fall through to fail unless we can recover - actually fail
                // Try from after the star pattern again - simplified fail
            }
            pi = sp + 1;
            si = ss + 1;
            star_si = Some(ss + 1);
            if path.get(ss) == Some(&b'/') {
                // * doesn't match across /
                // reset star and fail this
                // Continue if path has more after we skip - actually for * we stop at /
                return false;
            }
            continue;
        }
        return false;
    }

    // consume trailing * and **
    while pi < pat.len() {
        if pat[pi] == b'*' {
            if pi + 1 < pat.len() && pat[pi + 1] == b'*' {
                pi += 2;
                if pi < pat.len() && pat[pi] == b'/' {
                    pi += 1;
                }
            } else {
                pi += 1;
            }
        } else if pat[pi] == b'/' && pi + 1 < pat.len() && pat[pi + 1] == b'*' {
            pi += 1;
        } else {
            break;
        }
    }
    pi >= pat.len()
}

/// Global matcher used by the runner (mirrors module-level matchers array).
pub struct GlobalIgnores {
    inner: Mutex<IgnoreMatcher>,
}

impl GlobalIgnores {
    pub fn new() -> Self {
        Self {
            inner: Mutex::new(IgnoreMatcher::new()),
        }
    }

    pub fn add(&self, input: &[String]) {
        if let Ok(mut g) = self.inner.lock() {
            g.add_from_input(input);
        }
    }

    pub fn add_from_file(&self, paths: &[String]) {
        if let Ok(mut g) = self.inner.lock() {
            g.add_from_file(paths);
        }
    }

    pub fn should_ignore(&self, path: &str) -> bool {
        self.inner
            .lock()
            .map(|g| g.should_ignore(path))
            .unwrap_or(false)
    }
}

impl Default for GlobalIgnores {
    fn default() -> Self {
        Self::new()
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn ignores_node_modules() {
        let mut m = IgnoreMatcher::new();
        m.add_pattern("**/node_modules/**");
        assert!(m.should_ignore("foo/node_modules/bar.js"));
        assert!(m.should_ignore("../src/node_modules/bar.js"));
    }
}
