const CHUNK_SIZE: usize = 50;

#[derive(Debug, Default, Clone)]
pub struct FileStats {
    pub error: usize,
    pub ok: usize,
    pub nochange: usize,
    pub skip: usize,
}

#[derive(Debug, Clone, Serialize, Deserialize)]
#[serde(tag = "action")]
pub enum WorkerMessage {
