fn line_break(s: &str) -> String {
    if s.ends_with('\n') {
        s.to_string()
    } else {
        format!("{}\n", s)
    }
}

fn log_status(status: &str, msg: &str, verbose: i32) {
    match status {
        "ok" => {
            if verbose >= 2 {
                print!("{}{}", " OKK ".on_green().white(), msg);
            }
        }
        "nochange" => {
            if verbose >= 1 {
                print!("{}{}", " NOC ".on_yellow().white(), msg);
            }
        }
        "skip" => {
            if verbose >= 1 {
                print!("{}{}", " SKIP ".on_yellow().white(), msg);
            }
        }
        "error" => {
            if verbose >= 0 {
                print!("{}{}", " ERR ".on_red().white(), msg);
            }
        }
        _ => {}
    }
    let _ = std::io::stdout().flush();
}

fn report(file: &str, msg: &str) {
    print!(
        "{}",
        line_break(&format!("{}{} {}", " REP ".on_blue().white(), file, msg))
    );
    let _ = std::io::stdout().flush();
}

fn show_file_stats(stats: &FileStats) {
    print!(
        "Results: \n{}{}{}{}",
        format!("{} errors\n", stats.error).red(),
        format!("{} unmodified\n", stats.nochange).yellow(),
        format!("{} skipped\n", stats.skip).yellow(),
        format!("{} ok\n", stats.ok).green()
    );
}

fn show_stats(stats: &HashMap<String, usize>) {
    let mut names: Vec<_> = stats.keys().cloned().collect();
    names.sort();
    if !names.is_empty() {
        print!("{}", "Stats: \n".blue());
    }
    for name in names {
        println!("{}: {}", name, stats[&name]);
    }
}

fn extension_matches(name: &str, extensions: &Option<Vec<String>>) -> bool {
    match extensions {
        None => true,
        Some(exts) => {
            let ext = Path::new(name)
                .extension()
                .and_then(|e| e.to_str())
                .map(|e| format!(".{}", e))
                .unwrap_or_default();
            exts.iter().any(|e| e == &ext)
        }
    }
}

fn collect_files(paths: &[String], extensions: &Option<Vec<String>>, ignores: &GlobalIgnores) -> Vec<String> {
    let mut result = Vec::new();

    for file in paths {
        if file.is_empty() {
            continue;
        }
        let path = Path::new(file);
        let meta = match fs::symlink_metadata(path) {
            Ok(m) => m,
            Err(_) => {
                eprint!("Skipping path {} which does not exist. \n", file);
                continue;
            }
        };

        if meta.is_dir() {
            collect_dir(path, extensions, ignores, &mut result);
        } else if !extension_matches(file, extensions) || ignores.should_ignore(file) {
            // ignore
        } else {
            result.push(file.to_string());
        }
    }
    result
}

fn collect_dir(
    dir: &Path,
    extensions: &Option<Vec<String>>,
    ignores: &GlobalIgnores,
    acc: &mut Vec<String>,
) {
    let entries = match fs::read_dir(dir) {
        Ok(e) => e,
        Err(err) => {
            // JS throws on readdir error
            panic!("{}", err);
        }
    };

    for entry in entries.flatten() {
        let name = entry.path();
        let name_str = name.to_string_lossy().to_string();

        let meta = match fs::metadata(&name) {
            Ok(m) => m,
            Err(_) => {
                println!("Skipping path \"{}\" which does not exist.", name_str);
                continue;
            }
        };

        if ignores.should_ignore(&name_str) {
            continue;
        }

        if meta.is_dir() {
            // JS joins with name + '/'
            collect_dir(&name, extensions, ignores, acc);
        } else if extension_matches(&name_str, extensions) {
            acc.push(name_str);
        }
    }
}

fn download_transform(url: &str) -> Result<PathBuf, String> {
    let response = ureq::get(url)
        .call()
        .map_err(|e| format!("Failed to download transform: {}", e))?;
    let contents = response
        .into_string()
        .map_err(|e| format!("Failed to read transform body: {}", e))?;

    let ext = Path::new(url)
        .extension()
        .and_then(|e| e.to_str())
        .map(|e| format!(".{}", e))
        .unwrap_or_else(|| ".js".to_string());

    let tmp = tempfile::Builder::new()
        .prefix("jscodeshift")
        .suffix(&ext)
        .tempfile()
        .map_err(|e| format!("{}", e))?;
    let path = tmp.path().to_path_buf();
    // Keep file by persisting
    let (mut f, path) = tmp
        .keep()
        .map_err(|e| format!("{}", e))?;
    f.write_all(contents.as_bytes())
        .map_err(|e| format!("{}", e))?;
    Ok(path)
}

fn bridge_script_path() -> PathBuf {
    package_root().join("bridge").join("transform-host.js")
}

/// Run the jscodeshift transform pipeline.
pub fn run(transform_file: &str, paths: Vec<String>, options: HashMap<String, Value>) -> Result<Value, i32> {
    let available_cpus = std::cmp::max(num_cpus::get().saturating_sub(1), 1);
    let cpus = opt_u32(&options, "cpus")
        .map(|c| std::cmp::min(available_cpus, c as usize))
        .unwrap_or(available_cpus);

    let extensions: Option<Vec<String>> = opt_str(&options, "extensions").map(|s| {
        s.split(',')
            .map(|ext| format!(".{}", ext.trim()))
            .collect()
    });

    let ignores = GlobalIgnores::new();
    // options.ignoreSet is used in JS but never set by CLI - keep for API parity
    if let Some(Value::Array(arr)) = options.get("ignoreSet") {
        let pats: Vec<String> = arr
            .iter()
            .filter_map(|v| v.as_str().map(|s| s.to_string()))
            .collect();
        ignores.add(&pats);
    }
    let ignore_pattern = opt_string_list(&options, "ignorePattern");
    ignores.add(&ignore_pattern);
    let ignore_config = opt_string_list(&options, "ignoreConfig");
    ignores.add_from_file(&ignore_config);

    if opt_bool(&options, "gitignore", false) {
        let gitignore = std::env::current_dir()
            .map(|d| d.join(".gitignore"))
            .unwrap_or_else(|_| PathBuf::from(".gitignore"));
        ignores.add_from_file(&[gitignore.to_string_lossy().to_string()]);
    }

    let transform_path = if transform_file.starts_with("http://") || transform_file.starts_with("https://") {
        match download_transform(transform_file) {
            Ok(p) => p.to_string_lossy().to_string(),
            Err(e) => {
                eprintln!("{}", e);
                return Err(1);
            }
        }
    } else if !Path::new(transform_file).exists() {
        eprint!(
            "{} Transform file {} does not exist \n",
            "ERROR".on_red().white(),
            transform_file
        );
        return Ok(Value::Null);
    } else {
        transform_file.to_string()
    };

    let silent = opt_bool(&options, "silent", false);
    let dry = opt_bool(&options, "dry", false);
    let run_in_band = opt_bool(&options, "runInBand", false);
    let verbose = opt_u32(&options, "verbose").unwrap_or(0) as i32;
    let fail_on_error = opt_bool(&options, "failOnError", false);
    let babel = opt_bool(&options, "babel", true);

    let start = Instant::now();

    let files = collect_files(&paths, &extensions, &ignores);
    let num_files = files.len();

    if num_files == 0 {
        print!("No files selected, nothing to do. \n");
        return Ok(json!([]));
    }

    let processes = if run_in_band {
        1
    } else {
        std::cmp::min(num_files, cpus)
    };
    let chunk_size = if processes > 1 {
        std::cmp::min((num_files + processes - 1) / processes, CHUNK_SIZE)
    } else {
        num_files
    };

    if !silent {
        print!("Processing {} files... \n", files.len());
        if !run_in_band {
            print!("Spawning {} workers...\n", processes);
        }
        if dry {
            print!(
                "{}",
                "Running in dry mode, no files will be written! \n".green()
            );
        }
        let _ = std::io::stdout().flush();
    }

    let file_counters = Arc::new(Mutex::new(FileStats::default()));
    let stats_counter: Arc<Mutex<HashMap<String, usize>>> = Arc::new(Mutex::new(HashMap::new()));
    let next_index = Arc::new(AtomicUsize::new(0));
    let files = Arc::new(files);

    let bridge = bridge_script_path();
    if !bridge.exists() {
        eprintln!(
            "Transform bridge not found at {}. Did you run the build?",
            bridge.display()
        );
        return Err(1);
    }

    let babel_arg = if babel { "babel" } else { "no-babel" };
    let root = package_root();

    // Spawn workers
    let mut handles = Vec::new();

    for worker_id in 0..processes {
        let files = Arc::clone(&files);
        let next_index = Arc::clone(&next_index);
        let file_counters = Arc::clone(&file_counters);
        let stats_counter = Arc::clone(&stats_counter);
        let options = options.clone();
        let transform_path = transform_path.clone();
        let bridge = bridge.clone();
        let root = root.clone();
        let babel_arg = babel_arg.to_string();
        let silent = silent;
        let run_in_band = run_in_band;
        let verbose = verbose;
        let chunk_size = chunk_size;
        let num_files = num_files;

        let handle = std::thread::spawn(move || {
            let mut child = match Command::new("node")
                .arg(&bridge)
                .arg(&transform_path)
                .arg(&babel_arg)
                .current_dir(&root)
                .stdin(Stdio::piped())
                .stdout(Stdio::piped())
                .stderr(Stdio::inherit())
                .env("JSCODESHIFT_ROOT", root.to_string_lossy().as_ref())
                .spawn()
            {
                Ok(c) => c,
                Err(e) => {
                    eprintln!("Failed to spawn worker: {}", e);
                    return;
                }
            };

            let mut stdin = child.stdin.take().expect("stdin");
            let stdout = child.stdout.take().expect("stdout");
            let mut reader = BufReader::new(stdout);

            loop {
                let start_idx = next_index.fetch_add(chunk_size, Ordering::SeqCst);
                if start_idx >= num_files {
                    // Send empty to signal done
                    let msg = json!({"files": [], "options": options});
                    let _ = writeln!(stdin, "{}", msg);
                    let _ = stdin.flush();
                    break;
                }
                let end_idx = std::cmp::min(start_idx + chunk_size, num_files);
                let chunk: Vec<String> = files[start_idx..end_idx].to_vec();

                if !silent && !run_in_band {
                    print!(
                        "Sending {} files to free worker...\n",
                        chunk.len()
                    );
                    let _ = std::io::stdout().flush();
                }

                let msg = json!({"files": chunk, "options": options});
                if writeln!(stdin, "{}", msg).is_err() {
                    break;
                }
                if stdin.flush().is_err() {
                    break;
                }

                // Read messages until free or done
                let mut line = String::new();
                loop {
                    line.clear();
                    match reader.read_line(&mut line) {
                        Ok(0) => break, // EOF
                        Ok(_) => {
                            let line = line.trim();
                            if line.is_empty() {
                                continue;
                            }
                            match serde_json::from_str::<WorkerMessage>(line) {
                                Ok(WorkerMessage::Status { status, msg }) => {
                                    if let Ok(mut c) = file_counters.lock() {
                                        match status.as_str() {
                                            "error" => c.error += 1,
                                            "ok" => c.ok += 1,
                                            "nochange" => c.nochange += 1,
                                            "skip" => c.skip += 1,
                                            _ => {}
                                        }
                                    }
                                    log_status(&status, &line_break(&msg), verbose);
                                }
                                Ok(WorkerMessage::Update { name, quantity }) => {
                                    if let Ok(mut s) = stats_counter.lock() {
                                        *s.entry(name).or_insert(0) += quantity;
                                    }
                                }
                                Ok(WorkerMessage::Report { file, msg }) => {
                                    report(&file, &msg);
                                }
                                Ok(WorkerMessage::Free) => {
                                    break; // get next chunk
                                }
                                Ok(WorkerMessage::Done) => {
                                    // Worker exiting
                                    let _ = child.wait();
                                    return;
                                }
                                Err(e) => {
                                    // Might be non-JSON stdout from transform print
                                    // Forward as-is if it looks like plain output
                                    if line.starts_with('{') {
                                        eprintln!("Bad worker message: {} ({})", line, e);
                                    } else {
                                        println!("{}", line);
                                    }
                                }
                            }
                        }
                        Err(_) => break,
                    }
                }
            }

            // Drain remaining messages
            let mut line = String::new();
            while reader.read_line(&mut line).unwrap_or(0) > 0 {
                let trimmed = line.trim();
                if let Ok(msg) = serde_json::from_str::<WorkerMessage>(trimmed) {
                    match msg {
                        WorkerMessage::Status { status, msg } => {
                            if let Ok(mut c) = file_counters.lock() {
                                match status.as_str() {
                                    "error" => c.error += 1,
                                    "ok" => c.ok += 1,
                                    "nochange" => c.nochange += 1,
                                    "skip" => c.skip += 1,
                                    _ => {}
                                }
                            }
                            log_status(&status, &line_break(&msg), verbose);
                        }
                        WorkerMessage::Update { name, quantity } => {
                            if let Ok(mut s) = stats_counter.lock() {
                                *s.entry(name).or_insert(0) += quantity;
                            }
                        }
                        WorkerMessage::Report { file, msg } => {
                            report(&file, &msg);
                        }
                        _ => {}
                    }
                } else if !trimmed.is_empty() && !trimmed.starts_with('{') {
                    println!("{}", trimmed);
                }
                line.clear();
            }
            let _ = child.wait();
            let _ = worker_id; // silence
        });

        handles.push(handle);
    }

    for h in handles {
        let _ = h.join();
    }

    let elapsed = start.elapsed().as_secs_f64();
    let time_elapsed = format!("{:.3}", elapsed);

    let counters = file_counters.lock().unwrap().clone();
    let stats = stats_counter.lock().unwrap().clone();

    if !silent {
        print!("All done. \n");
        show_file_stats(&counters);
        show_stats(&stats);
        print!("Time elapsed: {}seconds \n", time_elapsed);
        let _ = std::io::stdout().flush();

        if fail_on_error && counters.error > 0 {
            std::process::exit(1);
        }
    }

    let mut result = json!({
        "stats": stats,
        "timeElapsed": time_elapsed,
        "error": counters.error,
        "ok": counters.ok,
        "nochange": counters.nochange,
        "skip": counters.skip,
    });

    // Keep shape compatible
    if let Some(obj) = result.as_object_mut() {
        obj.insert("error".into(), json!(counters.error));
        obj.insert("ok".into(), json!(counters.ok));
        obj.insert("nochange".into(), json!(counters.nochange));
        obj.insert("skip".into(), json!(counters.skip));
    }

    Ok(result)
}
"}

{"path":"/workspace/codebase/rust/src/main.rs","command":"create","file_text":"use jscodeshift::args::{
