use jscodeshift::runner;
use std::io::{self, Read};

fn main() {
    let args: Vec<String> = std::env::args().skip(1).collect();

    let parsed = match parse_args(&args) {
        Ok(p) => p,
        Err(e) => {
            if e.exit_code != 0 {
                eprint!("{}", e.message);
                // Original writes message without forcing newline in some cases;
                // help/version already contain trailing content.
            } else {
                print!("{}", e.message);
            }
            std::process::exit(e.exit_code);
        }
    };

    let stdin_mode = opt_bool(&parsed.options, "stdin", false);

    if parsed.positional_arguments.is_empty() && !stdin_mode {
        eprint!(
            "Error: You have to provide at least one file/directory to transform.\n\n---\n\n{}",
            get_help_text()
        );
        std::process::exit(1);
    }

    let transform = opt_str(&parsed.options, "transform")
        .unwrap_or_else(|| "./transform.js".to_string());
    let transform = resolve_transform(&transform);

    let paths = if stdin_mode {
        let mut buffer = String::new();
        let _ = io::stdin().read_to_string(&mut buffer);
        buffer
            .split('\n')
            .map(|s| s.to_string())
            .collect::<Vec<_>>()
    } else {
        positional_to_strings(&parsed.positional_arguments)
    };

    match runner::run(&transform, paths, parsed.options) {
        Ok(_) => {}
        Err(code) => std::process::exit(code),
    }
}
