{"path":"/workspace/codebase/bridge/transform-host.js","command":"create","file_text":"#!/usr/bin/env node
/**
 * Transform host bridge: loads user transforms and runs them against files.
 * Protocol (newline-delimited JSON over stdin/stdout):
 *   stdin  -> { files: string[], options: object }
 *   stdout -> { action: 'status'|'update'|'free'|'report'|'done', ... }
 *
 * This is the minimal JS compatibility layer required to execute transforms
 * that depend on recast, babel parsers, and the jscodeshift Collection API.
 */

'use strict';

const path = require('path');
const readline = require('readline');

// Ensure package root is on module path
const packageRoot = process.env.JSCODESHIFT_ROOT || path.resolve(__dirname, '..');
if (!module.paths.includes(packageRoot)) {
  module.paths.unshift(packageRoot);
  module.paths.unshift(path.join(packageRoot, 'node_modules'));
}

const async = require('neo-async');
const fs = require('graceful-fs');
const writeFileAtomic = require('write-file-atomic');
const { DEFAULT_EXTENSIONS } = require('@babel/core');

// Use package-relative requires so this works regardless of cwd
const getParser = require(path.join(packageRoot, 'src', 'getParser'));
const jscodeshift = require(path.join(packageRoot, 'src', 'core'));

let presetEnv;
try {
  presetEnv = require('@babel/preset-env');
} catch (_) {}

const transformFile = process.argv[2];
const babelFlag = process.argv[3] || 'babel';

let transform;
let parserFromTransform;

function notify(data) {
  process.stdout.write(JSON.stringify(data) + '\n');
}

function finish() {
  notify({ action: 'done' });
  // Allow the write to flush
  setImmediate(() => process.exit(0));
}

function free() {
  notify({ action: 'free' });
}

function updateStatus(status, file, msg) {
  msg = msg ? file + ' ' + msg : file;
  notify({ action: 'status', status: status, msg: msg });
}

function report(file, msg) {
  notify({ action: 'report', file, msg });
}

function empty() {}

function stats(name, quantity) {
  quantity = typeof quantity !== 'number' ? 1 : quantity;
  notify({ action: 'update', name: name, quantity: quantity });
}

function trimStackTrace(trace) {
  if (!trace) {
    return '';
  }
  const lines = trace.split('\n');
  const result = [];
  lines.every(function (line) {
    if (line.indexOf(__filename) === -1) {
      result.push(line);
      return true;
    }
  });
  return result.join('\n');
}

function prepareJscodeshift(options) {
  const parser = parserFromTransform ||
    getParser(options.parser, options.parserConfig);
  return jscodeshift.withParser(parser);
}

function setup(tr, babel) {
  if (babel === 'babel') {
    const presets = [];
    if (presetEnv) {
      presets.push([
        presetEnv.default,
        { targets: { node: true } },
      ]);
    }
    presets.push(
      /\.tsx?$/.test(tr)
        ? require('@babel/preset-typescript').default
        : require('@babel/preset-flow').default
    );

    require('@babel/register')({
      configFile: false,
      babelrc: false,
      presets,
      plugins: [
        require('@babel/plugin-transform-class-properties').default,
        require('@babel/plugin-transform-nullish-coalescing-operator').default,
        require('@babel/plugin-transform-optional-chaining').default,
        require('@babel/plugin-transform-modules-commonjs').default,
        require('@babel/plugin-transform-private-methods').default,
      ],
      extensions: [...DEFAULT_EXTENSIONS, '.ts', '.tsx'],
      ignore: [
        /@babel\/parser/,
        /\/flow-parser\//,
        /\/recast\//,
        /\/ast-types\//,
      ],
    });
  }

  const mod = require(tr);
  transform = typeof mod.default === 'function' ? mod.default : mod;
  if (mod.parser) {
    parserFromTransform =
      typeof mod.parser === 'string' ? getParser(mod.parser) : mod.parser;
  }
}

function run(data) {
  const files = data.files;
  const options = data.options || {};
  if (!files.length) {
    finish();
    return;
  }
  async.each(
    files,
    function (file, callback) {
      fs.readFile(file, async function (err, source) {
        if (err) {
          updateStatus('error', file, 'File error: ' + err);
          callback();
          return;
        }
        source = source.toString();
        try {
          const j = prepareJscodeshift(options);
          const out = await transform(
            {
              path: file,
              source: source,
            },
            {
              j: j,
              jscodeshift: j,
              stats: options.dry ? stats : empty,
              report: (msg) => report(file, msg),
            },
            options
          );
          if (!out || out === source) {
            updateStatus(out ? 'nochange' : 'skip', file);
            callback();
            return;
          }
          if (options.print) {
            // Print transformed source to stderr so it doesn't break the JSON protocol.
            // Original Worker printed to console.log (stdout). The Rust runner
            // multiplexes worker stdout as the control channel, so we emit a
            // dedicated "print" action and also write to fd 3 if available,
            // falling back to process.stderr for visibility.
            // To preserve observable behavior for --print users, emit via a
            // side-channel message the runner will forward to real stdout.
            notify({ action: 'print', output: out });
          }
          if (!options.dry) {
            writeFileAtomic(file, out, function (err) {
              if (err) {
                updateStatus('error', file, 'File writer error: ' + err);
              } else {
                updateStatus('ok', file);
              }
              callback();
            });
          } else {
            updateStatus('ok', file);
            callback();
          }
        } catch (err) {
          updateStatus(
            'error',
            file,
            'Transformation error (' +
              err.message.replace(/\n/g, ' ') +
              ')\n' +
              trimStackTrace(err.stack)
          );
          callback();
        }
      });
    },
    function (err) {
      if (err) {
        updateStatus('error', '', 'This should never be shown!');
      }
      free();
    }
  );
}

// Setup transform on startup
try {
  setup(transformFile, babelFlag);
} catch (err) {
  notify({
    action: 'status',
    status: 'error',
    msg: 'Setup error: ' + (err && err.message ? err.message : String(err)),
  });
  finish();
  process.exit(1);
}

const rl = readline.createInterface({ input: process.stdin, crlfDelay: Infinity });
rl.on('line', (line) => {
  line = line.trim();
  if (!line) return;
  try {
    const data = JSON.parse(line);
    run(data);
  } catch (e) {
    notify({
      action: 'status',
      status: 'error',
      msg: 'Invalid worker message: ' + e.message,
    });
    free();
  }
});
rl.on('close', () => {
  finish();
});
"}

