/**
 * Copyright (c) Facebook, Inc. and its affiliates.
 *
 * This source code is licensed under the MIT license found in the
 * LICENSE file in the root directory of this source tree.
 *
 * Programmatic runner API. Delegates to the Rust implementation when the
 * native binary is available; otherwise falls back to a Node orchestration
 * path that still uses the transform-host bridge.
 */

'use strict';

const { spawn } = require('child_process');
const fs = require('fs');
const path = require('path');
const pc = require('picocolors');

const packageRoot = path.resolve(__dirname, '..');

function findBinary() {
  const candidates = [
    path.join(packageRoot, 'native', 'jscodeshift'),
    path.join(packageRoot, 'native', 'jscodeshift.exe'),
    path.join(packageRoot, 'rust', 'target', 'release', 'jscodeshift'),
    path.join(packageRoot, 'rust', 'target', 'debug', 'jscodeshift'),
  ];
  for (const c of candidates) {
    if (fs.existsSync(c)) return c;
  }
  return null;
}

/**
 * Run a transform. Mirrors the historical Runner.run(transformFile, paths, options)
 * signature and return shape.
 */
function run(transformFile, paths, options) {
  options = options || {};
  const bin = findBinary();

  if (bin) {
    return runNative(bin, transformFile, paths, options);
  }
  // Fallback pure-JS path for environments without the native binary built yet
  return runJsFallback(transformFile, paths, options);
}

function runNative(bin, transformFile, paths, options) {
  return new Promise((resolve, reject) => {
    const args = [];
    // Reconstruct CLI flags from options object
    const flagMap = {
      dry: { flag: true, full: 'dry' },
      print: { flag: true, full: 'print' },
      babel: { flag: true, full: 'babel' },
      silent: { flag: true, full: 'silent' },
      runInBand: { flag: true, full: 'run-in-band' },
      failOnError: { flag: true, full: 'fail-on-error' },
      gitignore: { flag: true, full: 'gitignore' },
      stdin: { flag: true, full: 'stdin' },
      cpus: { full: 'cpus' },
      verbose: { full: 'verbose' },
      extensions: { full: 'extensions' },
      parser: { full: 'parser' },
      transform: { full: 'transform' },
    };

    args.push('--transform', transformFile);

    for (const [key, meta] of Object.entries(flagMap)) {
      if (key === 'transform') continue;
      if (!(key in options)) continue;
      const val = options[key];
      if (meta.flag) {
        if (val === false) args.push(`--no-${meta.full}`);
        else if (val) args.push(`--${meta.full}`);
      } else if (val !== undefined && val !== null) {
        args.push(`--${meta.full}`, String(val));
      }
    }

    if (Array.isArray(options.ignorePattern)) {
      for (const p of options.ignorePattern) {
        args.push('--ignore-pattern', p);
      }
    } else if (typeof options.ignorePattern === 'string') {
      args.push('--ignore-pattern', options.ignorePattern);
    }

    if (Array.isArray(options.ignoreConfig)) {
      for (const p of options.ignoreConfig) {
        args.push('--ignore-config', p);
      }
    } else if (typeof options.ignoreConfig === 'string') {
      args.push('--ignore-config', options.ignoreConfig);
    }

    // Pass through unknown custom options
    const known = new Set([
      ...Object.keys(flagMap),
      'ignorePattern',
      'ignoreConfig',
      'ignoreSet',
      'parserConfig',
    ]);
    for (const [key, val] of Object.entries(options)) {
      if (known.has(key)) continue;
      if (typeof val === 'boolean') {
        if (val) args.push(`--${key}`);
        else args.push(`--no-${key}`);
      } else if (val !== undefined && val !== null) {
        args.push(`--${key}`, typeof val === 'object' ? JSON.stringify(val) : String(val));
      }
    }

    if (options.parserConfig && typeof options.parserConfig === 'object') {
      // Write temp parser config file
      const tmp = require('tmp');
      const tmpfile = tmp.fileSync({ postfix: '.json' });
      fs.writeFileSync(tmpfile.name, JSON.stringify(options.parserConfig));
      args.push('--parser-config', tmpfile.name);
    }

    for (const p of paths) {
      args.push(String(p));
    }

    const child = spawn(bin, args, {
      stdio: ['inherit', 'pipe', 'pipe'],
      env: { ...process.env, JSCODESHIFT_ROOT: packageRoot },
    });

    let stdout = '';
    let stderr = '';
    child.stdout.on('data', (d) => {
      stdout += d.toString();
      if (!options.silent) process.stdout.write(d);
    });
    child.stderr.on('data', (d) => {
      stderr += d.toString();
      if (!options.silent) process.stderr.write(d);
    });

    child.on('error', reject);
    child.on('exit', (code) => {
      // Parse summary from stdout if possible; otherwise return a basic result
      const result = {
        error: 0,
        ok: 0,
        nochange: 0,
        skip: 0,
        stats: {},
        timeElapsed: '0.000',
      };
      const errMatch = stdout.match(/(\d+) errors/);
      const nocMatch = stdout.match(/(\d+) unmodified/);
      const skipMatch = stdout.match(/(\d+) skipped/);
      const okMatch = stdout.match(/(\d+) ok/);
      const timeMatch = stdout.match(/Time elapsed: ([0-9.]+)seconds/);
      if (errMatch) result.error = Number(errMatch[1]);
      if (nocMatch) result.nochange = Number(nocMatch[1]);
      if (skipMatch) result.skip = Number(skipMatch[1]);
      if (okMatch) result.ok = Number(okMatch[1]);
      if (timeMatch) result.timeElapsed = timeMatch[1];

      if (code && options.failOnError) {
        // Native already exited non-zero
      }
      resolve(result);
    });
  });
}

function runJsFallback(transformFile, paths, options) {
  // Minimal in-process fallback using the original worker logic via bridge
  const Worker = require('./Worker');
  const ignores = require('./ignoreFiles');
  const availableCpus = Math.max(require('os').cpus().length - 1, 1);
  const cpus = options.cpus ? Math.min(availableCpus, options.cpus) : availableCpus;
  const extensions =
    options.extensions && options.extensions.split(',').map((ext) => '.' + ext);
  const fileCounters = { error: 0, ok: 0, nochange: 0, skip: 0 };
  const statsCounter = {};
  const startTime = process.hrtime();

  ignores.add(options.ignoreSet);
  ignores.add(options.ignorePattern);
  ignores.addFromFile(options.ignoreConfig);
  if (options.gitignore) {
    ignores.addFromFile(path.join(process.cwd(), '.gitignore'));
  }

  if (!fs.existsSync(transformFile) && !/^http/.test(transformFile)) {
    process.stderr.write(
      pc.bgRed(pc.white('ERROR')) + ' Transform file ' + transformFile + ' does not exist \n'
    );
    return Promise.resolve(null);
  }

  function getAllFiles(paths, filter) {
    const result = [];
    function walk(p) {
      let stat;
      try {
        stat = fs.lstatSync(p);
      } catch (e) {
        process.stderr.write('Skipping path ' + p + ' which does not exist. \n');
        return;
      }
      if (stat.isDirectory()) {
        for (const f of fs.readdirSync(p)) {
          const name = path.join(p, f);
          try {
            const s = fs.statSync(name);
            if (ignores.shouldIgnore(name)) continue;
            if (s.isDirectory()) walk(name);
            else if (filter(name)) result.push(name);
          } catch (e) {
            process.stdout.write('Skipping path "' + name + '" which does not exist.\n');
          }
        }
      } else if (filter(p) && !ignores.shouldIgnore(p)) {
        result.push(p);
      }
    }
    for (const p of paths) walk(p);
    return Promise.resolve(result);
  }

  return getAllFiles(
    paths,
    (name) => !extensions || extensions.indexOf(path.extname(name)) !== -1
  ).then((files) => {
    if (files.length === 0) {
      process.stdout.write('No files selected, nothing to do. \n');
      return [];
    }
    const args = [transformFile, options.babel !== false ? 'babel' : 'no-babel'];
    const worker = Worker(args);

    return new Promise((resolve) => {
      let index = 0;
      const chunkSize = files.length;

      function next() {
        return files.slice(index, (index += chunkSize));
      }

      if (!options.silent) {
        process.stdout.write('Processing ' + files.length + ' files... \n');
        if (options.dry) {
          process.stdout.write(
            pc.green('Running in dry mode, no files will be written! \n')
          );
        }
      }

      worker.send({ files: next(), options });
      worker.on('message', (message) => {
        switch (message.action) {
          case 'status':
            fileCounters[message.status] += 1;
            break;
          case 'update':
            if (!statsCounter[message.name]) statsCounter[message.name] = 0;
            statsCounter[message.name] += message.quantity;
            break;
          case 'free':
            worker.send({ files: next(), options });
            break;
        }
      });
      worker.on('disconnect', () => {
        const endTime = process.hrtime(startTime);
        const timeElapsed = (endTime[0] + endTime[1] / 1e9).toFixed(3);
        if (!options.silent) {
          process.stdout.write('All done. \n');
          process.stdout.write(
            'Results: \n' +
              pc.red(fileCounters.error + ' errors\n') +
              pc.yellow(fileCounters.nochange + ' unmodified\n') +
              pc.yellow(fileCounters.skip + ' skipped\n') +
              pc.green(fileCounters.ok + ' ok\n')
          );
          process.stdout.write('Time elapsed: ' + timeElapsed + 'seconds \n');
          if (options.failOnError && fileCounters.error > 0) process.exit(1);
        }
        resolve(
          Object.assign(
            { stats: statsCounter, timeElapsed: timeElapsed },
            fileCounters
          )
        );
      });
    });
  });
}

exports.run = run;
