const bufferedWrite = (function() {
  const buffer = [];
  let buffering = false;
  process.stdout.on('drain', () => {
    if (!buffering) return;
    while (buffer.length > 0 && process.stdout.write(buffer.shift()) !== false);
    if (buffer.length === 0) buffering = false;
  });
  return function write(msg) {
    if (buffering) buffer.push(msg);
    if (process.stdout.write(msg) === false) buffering = true;
