  skip(msg, verbose) { verbose >= 1 && bufferedWrite(pc.bgYellow(pc.white(' SKIP ')) + msg); },
  error(msg, verbose) { verbose >= 0 && bufferedWrite(pc.bgRed(pc.white(' ERR ')) + msg); },
};

function report({file, msg}) {
  bufferedWrite(lineBreak(`${pc.bgBlue(pc.white(' REP '))}${file} ${msg}`));
}

function concatAll(arrays) {
